"""A ledger of trades."""


class TradeLedger:
    def __init__(self, trades=()):
        self._trades = list(trades)

    def trades(self):
        """Return the trades held (a copy, so callers cannot change the ledger)."""
        return list(self._trades)

    def add(self, trade):
        """Add one trade to the ledger."""
        self.trades().append(trade)

    def total(self):
        """Return the total volume of the trades held."""
        return sum(x.volume for x in self._trades)


def describe_trade(trade):
    """Return a one-line description of a trade."""
    return "%s: %s" % (trade.desk, trade.volume)

